import{z as c,x as E,o as n,c as p,q as r,j as l,D as o,d as a,s as d,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"强度削弱与归纳变量","description":"","frontmatter":{"title":"强度削弱与归纳变量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strength-reduction-iv.md","filePath":"cs/strength-reduction-iv.md","lastUpdated":1791413859000}'),A={name:"cs/strength-reduction-iv.md"};function B(h,e,m,u,D,C){const t=E("Mermaid");return n(),p("div",null,[e[2]||(e[2]=r('<h1 id="强度削弱与归纳变量" tabindex="-1">强度削弱与归纳变量 <a class="header-anchor" href="#强度削弱与归纳变量" aria-label="Permalink to &quot;强度削弱与归纳变量&quot;">​</a></h1><div class="epigraph"><p>归纳变量每圈加常数；乘以常数的地址可改成每圈加法。强度削弱把贵运算换成便宜更新。</p><footer>—— 据 Allen, Cocke, Cocke–Kennedy；龙书归纳变量；Muchnick 整理</footer></div><p>上一课<a href="/cs/licm">LICM</a>把不变式搬出去。缺口是<strong>随圈线性变</strong>的量：<code>a[i]</code> 的地址 <code>&amp;a + i*sizeof</code>。基本归纳变量 \\(i\\)，派生 \\(j=4*i+b\\)。削弱：循环外算初值，圈内 <code>j+=4</code>。本课钉 IV 与削弱，不写展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>识别：SSA 上 \\(i = \\phi(i_0, i+c)\\) 形态。派生：循环内 \\(j = i*k + b\\) 且 \\(k,b\\) 不变。缺口是<strong>改写合法性</strong>（溢出、指针 provenance），不是外提。</p><p><span class="marginnote">数字实例：<code>a[i]</code> 每元素 4 字节，第 i 圈地址是 <code>base + 4*i</code>——这个乘法每圈都做一次；削弱后初值 <code>base</code> 只在循环外算一次，圈内改成 <code>p += 4</code>，把 n 次乘法换成 n 次加法。</span></p><p><span class="marginnote">直觉类比：归纳变量像跑步时的计圈器与配速表——计圈器（i）每圈加一，配速表（j）本可由计圈器换算出来；既然两者步调固定，干脆让配速表自己按固定步幅走，不再每圈回头换算。</span></p><p>删除无用 IV：若 \\(i\\) 只服务地址，削弱后 \\(i\\) 可 DCE。比较：<code>i&lt;n</code> 可改成 <code>p&lt;end</code>，少一个名——重写退出条件。</p><h3 id="削弱不是「乘法变移位」的窥孔" tabindex="-1">削弱不是「乘法变移位」的窥孔 <a class="header-anchor" href="#削弱不是「乘法变移位」的窥孔" aria-label="Permalink to &quot;削弱不是「乘法变移位」的窥孔&quot;">​</a></h3><p>窥孔把 <code>*4</code> 变移位，是单条指令。IV 削弱是跨迭代的递推。二者都做，层不同。</p><p><span class="marginnote">Cocke–Kennedy 强度削弱。龙书 9.1.2。LLVM 的 IndVarSimplify。本课整数与指针；浮点归纳少见且危险。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>找循环的 φ 加法。建 IV 族。为每个派生插初始化与加法。更新比较。跑 DCE。</p>',13)),(n(),l(s,null,{default:o(()=>[d(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHI%5B%22i%20%3D%20%CF%86(i0%2C%20i%2Bc)%22%5D%20--%3E%20FAM%5B%22%E6%B4%BE%E7%94%9F%20j%20%3D%20k*i%2Bb%22%5D%0A%20%20FAM%20--%3E%20SR%5B%22j%20%2B%3D%20k*c%22%5D%0A%20%20SR%20--%3E%20DCE%5B%22%E5%88%A0%E6%97%A0%E7%94%A8%20i%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("p",null,"与寄存器：多个派生 IV 增加名，可能要合并或保留 \\(i\\)。启发。",-1)),e[4]||(e[4]=i("h2",{id:"机制",tabindex:"-1"},[a("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=i("p",null,[a("有符号溢出：C 中 \\(i\\) 递增若 UB，削弱后的指针运算须仍在对象内——语言规则。不要把 "),i("code",null,"i*i"),a(" 当线性 IV。")],-1)),e[6]||(e[6]=i("p",null,[a("非线性（"),i("code",null,"i*i"),a("）可差分化成递推，少见，点名。")],-1)),(n(),l(s,null,{default:o(()=>[d(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%94%B9%E5%86%99%E5%89%8D%EF%BC%9A%E5%BE%AA%E7%8E%AF%E5%86%85%20j%20%3D%204*i%20%2B%20b%22%5D%20--%3E%20C%5B%22%E5%BE%AA%E7%8E%AF%E5%A4%96%EF%BC%9Aj0%20%3D%204*i0%20%2B%20b%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%BE%AA%E7%8E%AF%E5%86%85%EF%BC%9Aj%20%E6%AF%8F%E5%9C%88%E5%8A%A0%204%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%AF%94%E8%BE%83%E6%94%B9%E5%86%99%EF%BC%9Ap%20%E4%B8%8E%20end%20%E6%AF%94%22%5D%0A%20%20E%20--%3E%20F%5B%22DCE%EF%BC%9A%E6%97%A7%20i%20%E4%B8%8E%E4%B9%98%E6%B3%95%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<p><span class="marginnote">常见误区：初学者容易把 <code>i*i</code> 也当归纳变量削弱，实际上它是二次的——每圈的增量本身在变，不是常数；要削它得先差分化把增量递推出来，编译器只在能证安全时才做。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写循环展开因子选择。后课默认：线性 IV 可削弱成加法。下一课展开与剥离：用已知行程复制体。</p><p>也不把强度削弱当密码学的「削弱」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基本 IV 每圈加常数；派生可递推更新。</li><li>削弱后 DCE 旧 IV；注意溢出与指针规则。</li><li>不同于单指令窥孔。</li><li>出处：Allen/Cocke/Kennedy；龙书；Muchnick。</li></ul>',6))])}const _=c(A,[["render",B]]);export{b as __pageData,_ as default};
